/*
 * Rotary Positional Embedding (RoPE) CUDA kernel — baseline implementation
 *
 * Applies rotary embeddings to query and key tensors.
 * For each pair (x_i, x_{i+d/2}), rotates by angle m * theta_i where:
 *   theta_i = 1 / (base^(2i/d))
 *   m = position index
 *
 * Used in LLaMA, Mistral, and most modern transformer models.
 */

#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

// ─── Kernel ──────────────────────────────────────────────────────────────────

template <typename scalar_t>
__global__ void rotary_embedding_kernel(
    scalar_t* __restrict__ x,          // [batch, seq_len, num_heads, head_dim]
    const int* __restrict__ positions,  // [batch, seq_len]
    int seq_len,
    int num_heads,
    int head_dim,
    float base,
    int total_pairs
) {
    // Each thread handles one (batch, seq, head, pair_idx) element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    // Bounds guard (benchmark change 00's reason, kept): the launcher rounds the grid up to 256-thread blocks, so
    // a decode step's k (4 K/V heads x 32 pairs = 128 pairs) runs stray threads that, unguarded, read and write
    // past the tensors (compute-sanitizer on an H100: the stock kernel's rotary_embedding.cu:34, thread 128).
    if (idx >= total_pairs) return;
    int half_dim = head_dim / 2;

    // Decode flat index → (batch, seq, head, pair)
    int pair_idx = idx % half_dim;
    int tmp = idx / half_dim;
    int head = tmp % num_heads;
    int tmp2 = tmp / num_heads;
    int seq = tmp2 % seq_len;
    int batch = tmp2 / seq_len;

    // Compute rotation angle the way HF does: inv_freq and angle in fp32.
    // sin/cos run in double because --use_fast_math swaps sinf/cosf/powf for
    // approximations that lose accuracy at large angles (long positions).
    int m = positions[batch * seq_len + seq];
    float theta = static_cast<float>(1.0 / pow(static_cast<double>(base),
                                               (2.0 * pair_idx) / head_dim));
    float angle = static_cast<float>(m) * theta;
    double sin_d, cos_d;
    sincos(static_cast<double>(angle), &sin_d, &cos_d);
    float cos_val = static_cast<float>(cos_d);
    float sin_val = static_cast<float>(sin_d);

    // Index into x: [batch, seq, head, head_dim]
    int base_idx = ((batch * seq_len + seq) * num_heads + head) * head_dim;
    int i0 = base_idx + pair_idx;
    int i1 = base_idx + pair_idx + half_dim;

    float x0 = static_cast<float>(x[i0]);
    float x1 = static_cast<float>(x[i1]);

    x[i0] = static_cast<scalar_t>(x0 * cos_val - x1 * sin_val);
    x[i1] = static_cast<scalar_t>(x1 * cos_val + x0 * sin_val);
}

// ─── Host wrapper ────────────────────────────────────────────────────────────

torch::Tensor agent_rotary_embedding(
    torch::Tensor x,          // [batch, seq_len, num_heads, head_dim]
    torch::Tensor positions,   // [batch, seq_len] int32
    double base
) {
    auto output = x.clone();
    int batch = x.size(0);
    int seq_len = x.size(1);
    int num_heads = x.size(2);
    int head_dim = x.size(3);
    int half_dim = head_dim / 2;

    int total_pairs = batch * seq_len * num_heads * half_dim;
    int threads = 256;
    int blocks = (total_pairs + threads - 1) / threads;

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half, at::ScalarType::BFloat16,
        x.scalar_type(), "rotary_embedding", [&] {
            rotary_embedding_kernel<scalar_t><<<blocks, threads>>>(
                output.data_ptr<scalar_t>(),
                positions.data_ptr<int>(),
                seq_len, num_heads, head_dim,
                static_cast<float>(base),
                total_pairs
            );
        }
    );

    return output;
}

input.newString:
/*
 * Rotary Positional Embedding (RoPE) CUDA kernel — optimized implementation
 *
 * Applies rotary embeddings to query and key tensors.
 * For each pair (x_i, x_{i+d/2}), rotates by angle m * theta_i where:
 *   theta_i = 1 / (base^(2i/d))
 *   m = position index
 *
 * Optimization: 1 block per (batch, seq) position. sin/cos for all pair_idx
 * values are precomputed once into shared memory by the first half_dim threads,
 * then all (head, pair_idx) threads read from shared memory. This eliminates
 * redundant pow() + sincos() calls across heads (32x fewer for Q, 4x for K).
 */

#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

// ─── Kernel ──────────────────────────────────────────────────────────────────

template <typename scalar_t>
__global__ void rotary_embedding_kernel(
    scalar_t* __restrict__ x,          // [batch, seq_len, num_heads, head_dim]
    const int* __restrict__ positions,  // [batch, seq_len]
    int seq_len,
    int num_heads,
    int head_dim,
    float base,
    int total_pairs
) {
    int half_dim = head_dim / 2;
    int bs_idx = blockIdx.x;
    int batch = bs_idx / seq_len;
    int seq = bs_idx % seq_len;

    int m = positions[bs_idx];

    __shared__ float smem_cos[64];
    __shared__ float smem_sin[64];

    if (threadIdx.x < half_dim) {
        float theta = static_cast<float>(1.0 / pow(static_cast<double>(base),
                                                    (2.0 * threadIdx.x) / head_dim));
        float angle = static_cast<float>(m) * theta;
        double sin_d, cos_d;
        sincos(static_cast<double>(angle), &sin_d, &cos_d);
        smem_cos[threadIdx.x] = static_cast<float>(cos_d);
        smem_sin[threadIdx.x] = static_cast<float>(sin_d);
    }
    __syncthreads();

    int total_elements = num_heads * half_dim;

    for (int idx = threadIdx.x; idx < total_elements; idx += blockDim.x) {
        int pair_idx = idx % half_dim;
        int head = idx / half_dim;

        float cos_val = smem_cos[pair_idx];
        float sin_val = smem_sin[pair_idx];

        int base_idx = (bs_idx * num_heads + head) * head_dim;
        int i0 = base_idx + pair_idx;
        int i1 = base_idx + pair_idx + half_dim;

        float x0 = static_cast<float>(x[i0]);
        float x1 = static_cast<float>(x[i1]);

        x[i0] = static_cast<scalar_t>(x0 * cos_val - x1 * sin_val);
        x[i1] = static_cast<scalar_t>(x1 * cos_val + x0 * sin_val);
    }
}

// ─── Host wrapper ────────────────────────────────────────────────────────────

torch::Tensor agent_rotary_embedding(
    torch::Tensor x,          // [batch, seq_len, num_heads, head_dim]
    torch::Tensor positions,   // [batch, seq_len] int32
    double base
) {
    auto output = x.clone();
    int batch = x.size(0);
    int seq_len = x.size(1);
    int num_heads = x.size(2);
    int head_dim = x.size(3);
    int half_dim = head_dim / 2;

    int blocks = batch * seq_len;
    int threads = min(num_heads * half_dim, 1024);
    threads = max(((threads + 31) / 32) * 32, 32);

    if (blocks > 0) {
        AT_DISPATCH_FLOATING_TYPES_AND2(
            at::ScalarType::Half, at::ScalarType::BFloat16,
            x.scalar_type(), "rotary_embedding", [&] {
                rotary_embedding_kernel<scalar_t><<<blocks, threads>>>(
                    output.data_ptr<scalar_t>(),
                    positions.data_ptr<int>(),
                    seq_len, num_heads, head_dim,
                    static_cast<float>(base),
                    batch * seq_len * num_heads * half_dim
                );
            }
        );
    }

    return output;
}

