#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>

template <typename scalar_t, int VEC_SIZE>
struct VecType {
    using type = typename std::conditional<VEC_SIZE * sizeof(scalar_t) == 16, uint4,
                     typename std::conditional<VEC_SIZE * sizeof(scalar_t) == 8, uint2,
                         typename std::conditional<VEC_SIZE * sizeof(scalar_t) == 4, uint32_t,
                             scalar_t>::type>::type>::type;
};

template <typename scalar_t>
__global__ __launch_bounds__(1024)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
