    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    constexpr int VEC = 4;
    using vec_t = typename VecType<scalar_t, VEC>::type;

    float sum_sq = 0.0f;
    int vec_iters = hidden_size / (blockDim.x * VEC);

    for (int iter = 0; iter < vec_iters; iter++) {
        int base_i = (iter * blockDim.x + threadIdx.x) * VEC;
        vec_t vx = *reinterpret_cast<const vec_t*>(&x[base_i]);
        const scalar_t* px = reinterpret_cast<const scalar_t*>(&vx);
        #pragma unroll
        for (int j = 0; j < VEC; j++) {
            float val = static_cast<float>(px[j]);
            sum_sq += val * val;
        }
    }

    // Handle remainder
    int remainder_start = vec_iters * blockDim.x * VEC;
    for (int i = remainder_start + threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        sum_sq += val * val;
