        int base_i = (iter * blockDim.x + threadIdx.x) * VEC;
        vec_t vx = *reinterpret_cast<const vec_t*>(&x[base_i]);
        vec_t vw = *reinterpret_cast<const vec_t*>(&weight[base_i]);
        const scalar_t* px = reinterpret_cast<const scalar_t*>(&vx);
